create table payment_test_results(name text primary key,result jsonb);
grant all on payment_test_results to authenticated;
create function pg_temp.expect_error(command text,fragment text) returns void language plpgsql as $$begin
 begin execute command;exception when others then if position(fragment in sqlerrm)=0 then raise exception 'Wrong error: % wanted %',sqlerrm,fragment;end if;return;end;
 raise exception 'Expected rejection: %',fragment;
end$$;
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','ed000000-0000-4000-8000-000000000001',true);
select receive_purchase_order('ed500000-0000-4000-8000-000000000001','receipt-pay-test','TB.PAY.FIC.',5,current_date,null,null,'[{"id":"ed600000-0000-4000-8000-000000000001","qty_terima":10,"qty_rusak":0}]');
insert into payment_test_results select 'invoice',to_jsonb(x) from create_purchase_invoice_from_po('ed500000-0000-4000-8000-000000000001','FB.PAY.FIC.',5,null,current_date,current_date,null,'[{"po_item_id":"ed600000-0000-4000-8000-000000000001","qty":10,"harga":100,"expected_harga_po":100,"expected_faktor":1}]','[]','[]',0,'invoice-pay-test')x;
insert into payment_test_results select 'partial',pay_purchase_invoice_atomic('partial-pay',(result->>'invoice_id')::uuid,current_date,300,'Transfer',null,'ed700000-0000-4000-8000-000000000001',null) from payment_test_results where name='invoice';
insert into payment_test_results select 'advance',pay_purchase_invoice_atomic('advance-pay',(result->>'invoice_id')::uuid,current_date,400,'Transfer',null,'ed700000-0000-4000-8000-000000000001','ed800000-0000-4000-8000-000000000001') from payment_test_results where name='invoice';
reset role;
insert into payment_test_results select 'source-journals',jsonb_agg(to_jsonb(j) order by id) from journal_entries j;
insert into payment_test_results select 'source-lines',jsonb_agg(to_jsonb(l) order by id) from journal_lines l;
insert into payment_test_results select 'source-stock',jsonb_agg(to_jsonb(s) order by id) from stock_layers s;
set local role authenticated;
do $$declare p uuid;iv uuid;r jsonb;rr jsonb;begin
 select (result->>'payment_id')::uuid into p from payment_test_results where name='advance';
 select (result->>'invoice_id')::uuid into iv from payment_test_results where name='invoice';
 perform pg_temp.expect_error(format('select cancel_purchase_payment(%L,99,%L,%L)',p,'stale','Wrong amount'),'berubah');
 perform pg_temp.expect_error(format('select cancel_purchase_payment(%L,0,%L,%L)',p,'reason','x'),'alasan');
 r:=cancel_purchase_payment(p,0,'advance-cancel','Wrong advance allocation');
 rr:=cancel_purchase_payment(p,0,'advance-cancel','Wrong advance allocation');
 if r is distinct from rr or get_purchase_payment_cancellation(p,'advance-cancel') is distinct from r then raise exception 'Lost-response cancellation recovery differs';end if;
 if (select terpakai from purchase_advances where id='ed800000-0000-4000-8000-000000000001')<>0 then raise exception 'Advance not restored exactly';end if;
 if (select sum(amount) from purchase_invoice_payments where invoice_id=iv)<>300 then raise exception 'Cancellation changed unrelated partial payment';end if;
 if not exists(select 1 from purchase_invoice_payments where id=p and amount=400 and dari_uang_muka=200 and voided_at is not null) then raise exception 'Original payment lost';end if;
 if not exists(select 1 from purchase_invoice_payments where reversal_of=p and amount=-400 and dari_uang_muka=-200) then raise exception 'Signed opposite not exact';end if;
 perform pg_temp.expect_error(format('select cancel_purchase_payment(%L,0,%L,%L)',p,'advance-cancel','Different reason'),'berbeda');
 perform pg_temp.expect_error(format('select cancel_purchase_payment(%L,0,%L,%L)',p,'advance-again','Wrong advance allocation'),'berubah');
 rr:=pay_purchase_invoice_atomic('replacement-pay',iv,current_date,100,'Transfer',null,'ed700000-0000-4000-8000-000000000001','ed800000-0000-4000-8000-000000000001',p);
 if (select terpakai from purchase_advances where id='ed800000-0000-4000-8000-000000000001')<>100 then raise exception 'Replacement advance not consumed';end if;
 perform pg_temp.expect_error(format('select pay_purchase_invoice_atomic(%L,%L,current_date,100,%L,null,null,null,%L)','replacement-again',iv,'Transfer',p),'pengganti sudah tersimpan');
 insert into payment_test_results values('replacement',rr);
end$$;
reset role;
do $$begin
 if (select jsonb_agg(to_jsonb(j) order by id) from journal_entries j where source<>'purchase-pay-void' and id not in(select (result->>'journal_id')::uuid from payment_test_results where name='replacement')) is distinct from (select result from payment_test_results where name='source-journals') then raise exception 'Original journals changed';end if;
 if (select jsonb_agg(to_jsonb(l) order by id) from journal_lines l where entry_id in(select id from journal_entries where source<>'purchase-pay-void' and id not in(select (result->>'journal_id')::uuid from payment_test_results where name='replacement'))) is distinct from (select result from payment_test_results where name='source-lines') then raise exception 'Original journal lines changed';end if;
 if (select jsonb_agg(to_jsonb(s) order by id) from stock_layers s) is distinct from (select result from payment_test_results where name='source-stock') then raise exception 'Payment cancellation modified inventory';end if;
end$$;
-- Final audit failure must roll back the reversal, advance restoration and void metadata.
create function payment_test_final_failure() returns trigger language plpgsql as $$begin raise exception 'PAYMENT_FINAL_FAULT';end$$;
create trigger payment_test_final_failure before insert on purchase_payment_cancellation_requests for each row execute function payment_test_final_failure();
set local role authenticated;
do $$declare p uuid;begin
 select (result->>'payment_id')::uuid into p from payment_test_results where name='replacement';
 perform pg_temp.expect_error(format('select cancel_purchase_payment(%L,0,%L,%L)',p,'fault-cancel','Final fault'),'PAYMENT_FINAL_FAULT');
 if exists(select 1 from purchase_invoice_payments where reversal_of=p) or (select voided_at from purchase_invoice_payments where id=p) is not null or (select terpakai from purchase_advances where id='ed800000-0000-4000-8000-000000000001')<>100 then raise exception 'Final failure leaked effects';end if;
end$$;
reset role;
drop trigger payment_test_final_failure on purchase_payment_cancellation_requests;
