do $$declare p uuid;o uuid;r jsonb;begin
 select (result->>'order_id')::uuid into o from payment_test_results where name='order';
 select id into p from purchase_invoice_payments where payment_order_id=o and amount>0 order by id limit 1;
 r:=cancel_purchase_payment(p,0,'order-cancel','Wrong payment account');
 if not exists(select 1 from payment_orders where id=o and status='disetujui' and paid_at is null and revision=3 and approved_by='ed000000-0000-4000-8000-000000000001') then raise exception 'Order approval state not restored';end if;
 if (select sum(amount) from purchase_invoice_payments where payment_order_id=o)<>0 then raise exception 'Order payment not reversed';end if;
 perform pg_temp.expect_error(format('select pay_purchase_payment_order_atomic(%L,%L,current_date,%L,null,1)','stale-order-pay',o,'Transfer'),'berubah');
 r:=pay_purchase_payment_order_atomic('order-repay',o,current_date,'Transfer','ed700000-0000-4000-8000-000000000001',3);
 if (select sum(amount) from purchase_invoice_payments where payment_order_id=o)<>250 then raise exception 'Order replacement payment duplicated';end if;
 perform pg_temp.expect_error(format('select mutate_purchase_payment_order(%L,%L,%L,4,%L,%L)','illegal-cancel','cancel',o,'{}','[]'),'Status');
end$$;
reset role;
do $$begin
 if (select sum(l.debit-l.credit) from journal_lines l join journal_entries j on j.id=l.entry_id join coa_accounts a on a.id=l.account_id where j.source='purchase-invoice' and j.source_ref='FB.PAY.VAT' and a.code='1202')<>11 then raise exception 'Payment correction modified input VAT';end if;
end$$;
