select pg_temp.expect_error(format('select pay_purchase_invoice_atomic(%L,%L,current_date,2,%L,null,null,null)','approval-too-small',result->>'invoice_id','Transfer'),'persetujuan') from payment_test_results where name='invoice';
select pay_purchase_invoice_atomic('approved-one',(result->>'invoice_id')::uuid,current_date,1,'Transfer',null,null,null) from payment_test_results where name='invoice';
select pg_temp.expect_error(format('select pay_purchase_invoice_atomic(%L,%L,current_date,1,%L,null,null,null)','approval-consumed',result->>'invoice_id','Transfer'),'persetujuan') from payment_test_results where name='invoice';
reset role;
delete from approval_rules where jenis='bayar-faktur';
commit;
